"""Render typed API methods from resolved operations.

``python -m tools.spec.generate`` writes ``src/familysearch/api/_ops.py``, one
module per API area and ``_api.py``. ``--check`` regenerates in memory and fails
if anything on disk differs. Output is pure string templating and is fully
determined by the resolved operations.
"""
import argparse
import dataclasses
import json
import keyword
from pathlib import Path

from familysearch.api.spec import OpSpec

from .resolve import MODULES, OVERRIDES_PATH, SNAPSHOT_PATH, ResolvedOp, load_overrides, resolve

HEADER = (
    "# GENERATED by tools/spec/generate.py — do not edit; "
    "run python -m tools.spec.generate"
)
DEFAULT_OUT = Path(__file__).resolve().parents[2] / "src" / "familysearch" / "api"
FIX_COMMAND = "python -m tools.spec.generate"

# Modules that get a generated file, in the order _api.py mixes them in.
EMITTED_MODULES = [m for m in MODULES.values() if m != "authentication"]
_OP_FIELDS = [f.name for f in dataclasses.fields(OpSpec)]
_RESERVED_PARAMS = {
    "self", "reason", "body", "files", "data", "data_content_type", "accept", "query",
    "allow_unverified", "allow_production", "confirm_destructive",
}
_WRITE_FLAGS = (
    "allow_unverified: bool = False, allow_production: bool = False, "
    "confirm_destructive: bool = False"
)
_BODY_PARAMS = {
    "none": "",
    "json": "body: Any = None",
    "upload": (
        "files: Mapping[str, Any] | None = None, data: bytes | None = None, "
        "data_content_type: str | None = None"
    ),
}
_BODY_ARGS = {
    "none": "",
    "json": "body=body",
    "upload": "files=files, data=data, data_content_type=data_content_type",
}


def class_name(module: str) -> str:
    return "".join(part.capitalize() for part in module.split("_")) + "Ops"


def _clean(text: str) -> str:
    """Collapse whitespace and replace control/non-printable characters with spaces."""
    return " ".join("".join(c if c.isprintable() else " " for c in text).split())


def _docstring(op: ResolvedOp) -> str:
    summary = _clean(op.summary) or op.operation_id
    text = _clean(f"{summary} ({op.http_method} {op.path}).")
    text = text.replace("\\", "\\\\").replace('"""', '\\"\\"\\"')
    if text.endswith('"'):
        text = text[:-1] + '\\"'
    return text


def _render_method(op: ResolvedOp) -> str:
    for name in op.path_params:
        if not name.isidentifier() or keyword.iskeyword(name) or name in _RESERVED_PARAMS:
            raise ValueError(
                f"{op.operation_id}: path parameter {name!r} cannot be a method argument"
            )
    if op.kind not in ("read", "write"):
        raise ValueError(f"{op.operation_id}: unexpected kind {op.kind!r}")
    if op.body not in _BODY_PARAMS:
        raise ValueError(f"{op.operation_id}: unexpected body kind {op.body!r}")
    params = [f"{name}: str" for name in op.path_params]
    params.insert(0, "self")
    kw = []
    call = []
    if op.kind == "write":
        kw.append("reason: str")
        call.append("reason=reason")
    if _BODY_PARAMS[op.body]:  # some read-classified POSTs carry a body
        kw.append(_BODY_PARAMS[op.body])
        call.append(_BODY_ARGS[op.body])
    if op.kind == "write":
        kw.append(_WRITE_FLAGS)
        call.append(
            "allow_unverified=allow_unverified, allow_production=allow_production, "
            "confirm_destructive=confirm_destructive"
        )
    kw.append("accept: str | None = None")
    kw.append("query: Mapping[str, Any] | None = None")
    call.append("accept=accept")
    call.append("query=query")
    path_args = "{" + ", ".join(f'"{n}": {n}' for n in op.path_params) + "}"
    signature = ", ".join(params + ["*"] + kw)
    return (
        f"    def {op.method_name}({signature}) -> ApiResult:\n"
        f'        """{_docstring(op)}"""\n'
        f'        return self._call(OPERATIONS["{op.operation_id}"], {path_args}, '
        f"{', '.join(call)})\n"
    )


def _lit(value) -> str:
    """Deterministic Python literal for an OpSpec field value."""
    if isinstance(value, str):
        return json.dumps(value)  # double quotes; escapes are valid Python
    if isinstance(value, tuple):
        items = ", ".join(_lit(v) for v in value)
        return f"({items},)" if len(value) == 1 else f"({items})"
    if isinstance(value, bool):
        return repr(value)
    raise TypeError(f"unsupported OpSpec value {value!r}")


def _render_entry(op: ResolvedOp) -> str:
    lines = [f"    {_lit(op.operation_id)}: OpSpec("]
    for name in _OP_FIELDS:
        lines.append(f"        {name}={_lit(getattr(op, name))},")
    lines.append("    ),")
    return "\n".join(lines)


def _render_ops(ops: list[ResolvedOp]) -> str:
    entries = "".join(
        _render_entry(op) + "\n" for op in sorted(ops, key=lambda o: o.operation_id)
    )
    return (
        f"{HEADER}\n"
        "from .spec import OpSpec\n\n"
        "OPERATIONS: dict[str, OpSpec] = {\n"
        f"{entries}"
        "}\n"
    )


def _render_module(module: str, ops: list[ResolvedOp]) -> str:
    methods = "\n".join(_render_method(op) for op in ops) or "    pass\n"
    return (
        f"{HEADER}\n"
        "from collections.abc import Mapping\n"
        "from typing import Any\n\n"
        "from ._ops import OPERATIONS\n"
        "from ._runtime import ApiResult\n\n\n"
        f"class {class_name(module)}:\n"
        f"{methods}"
    )


def _render_api() -> str:
    imports = "".join(
        f"from .{m} import {class_name(m)}\n" for m in sorted(EMITTED_MODULES)
    )
    bases = ", ".join(["ApiBase"] + [class_name(m) for m in EMITTED_MODULES])
    return (
        f"{HEADER}\n"
        f"{imports}"
        "from ._runtime import ApiBase\n\n\n"
        f"class FamilySearchApi({bases}):\n"
        "    pass\n"
    )


def render(ops: list[ResolvedOp], excluded: dict[str, str]) -> dict[str, str]:
    """Return ``{filename: text}``; ``excluded`` ops are simply not in ``ops``."""
    by_module: dict[str, list[ResolvedOp]] = {m: [] for m in EMITTED_MODULES}
    for op in ops:
        if op.module not in by_module:
            raise ValueError(f"{op.operation_id}: module {op.module!r} is not generated")
        by_module[op.module].append(op)
    files = {"_ops.py": _render_ops(ops), "_api.py": _render_api()}
    for module, module_ops in by_module.items():
        module_ops.sort(key=lambda o: o.operation_id)
        files[f"{module}.py"] = _render_module(module, module_ops)
    return dict(sorted(files.items()))


def write_all(out_dir: Path, rendered: dict[str, str] | None = None) -> list[Path]:
    out_dir = Path(out_dir)
    if rendered is None:
        rendered = _render_from_paths(SNAPSHOT_PATH, OVERRIDES_PATH)
    out_dir.mkdir(parents=True, exist_ok=True)
    written = []
    for name, text in rendered.items():
        path = out_dir / name
        path.write_text(text, encoding="utf-8", newline="\n")
        written.append(path)
    return written


def _render_from_paths(snapshot_path: Path, overrides_path: Path) -> dict[str, str]:
    snapshot = json.loads(Path(snapshot_path).read_text())
    ops, excluded = resolve(snapshot, load_overrides(Path(overrides_path)))
    return render(ops, excluded)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="python -m tools.spec.generate")
    parser.add_argument("--check", action="store_true", help="fail if generated files differ")
    parser.add_argument("--out", type=Path, default=DEFAULT_OUT)
    parser.add_argument("--snapshot", type=Path, default=SNAPSHOT_PATH)
    parser.add_argument("--overrides", type=Path, default=OVERRIDES_PATH)
    args = parser.parse_args(argv)
    rendered = _render_from_paths(args.snapshot, args.overrides)
    if args.check:
        for name, text in rendered.items():
            path = args.out / name
            current = path.read_text(encoding="utf-8") if path.exists() else None
            if current != text:
                state = "is missing" if current is None else "is out of date"
                print(f"{path} {state}; run {FIX_COMMAND}")
                return 1
        return 0
    for path in write_all(args.out, rendered):
        print(f"wrote {path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
